type Props = ComponentProps<typeof OnboardingTooltip>;
// PREVIOUS_BUTTON_SOURCE_GAP: source показывает Назад только при currentSlide > 0; фактический индекс не подменяется.
function Example({ anchor, visible, onClose, onClickNext, onClickPrev, onClickPips }: {
    anchor: Props['children']; visible: Props['visible']; onClose: NonNullable<Props['onClose']>;
    onClickNext: NonNullable<Props['onClickNext']>;
    onClickPrev: NonNullable<Props['onClickPrev']>;
    onClickPips: NonNullable<Props['onClickPips']>;


}) {
    return <OnboardingTooltip position="right-end" visible={visible} onClose={onClose}
        title={"Title 18-24"}
        subhead={"Subhead"}
        description={"Subtitle"}
        totalSlides={4} currentSlide={0}
        nextButtonText={"Label"} onClickNext={onClickNext}
        prevButtonText={"Label"} onClickPrev={onClickPrev}
        onClickPips={onClickPips}


    >{anchor}</OnboardingTooltip>;
}

